using BrassLedger.Application.Accounting;
using BrassLedger.Domain.Accounting;
using BrassLedger.Infrastructure.Auth;
using BrassLedger.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace BrassLedger.Infrastructure.Accounting;

public sealed partial class AccountingTransactionService
{
    public async Task<TransactionResult> CreditCustomerReturnAsync(CreditCustomerReturnRequest request, CancellationToken cancellationToken = default)
    {
        if (!HasPermission(BrassLedgerPermissions.ReceivablesManage)) return TransactionResult.Failure("You are not authorized to credit customer returns.");
        if (string.IsNullOrWhiteSpace(request.CreditNumber) || string.IsNullOrWhiteSpace(request.Reason)) return TransactionResult.Failure("A credit number and reason are required.");
        await using var db = await dbContextFactory.CreateDbContextAsync(cancellationToken); var companyId = await ResolveCompanyIdAsync(db, cancellationToken);
        var receipt = await db.CustomerReturnReceipts.SingleOrDefaultAsync(x => x.Id == request.CustomerReturnReceiptId && x.CompanyId == companyId, cancellationToken);
        if (receipt is null || receipt.Status != "Posted") return TransactionResult.Failure("Only a posted customer return receipt can be credited.");
        if (!string.Equals(receipt.ConcurrencyToken, request.ConcurrencyToken, StringComparison.Ordinal)) return TransactionResult.Failure("The return receipt changed after it was opened. Refresh and review it again.");
        if (request.CreditDate < receipt.ReceivedOn) return TransactionResult.Failure("The credit date cannot precede the return receipt date.");
        var creditNumber = request.CreditNumber.Trim();
        if (await db.CustomerReturnCredits.AnyAsync(x => x.CompanyId == companyId && (x.CreditNumber == creditNumber || x.CustomerReturnReceiptId == receipt.Id && x.Status == "Posted"), cancellationToken)) return TransactionResult.Failure("The credit number already exists or this return receipt already has an active credit.");
        var authorization = await db.CustomerReturnAuthorizations.SingleAsync(x => x.Id == receipt.CustomerReturnAuthorizationId && x.CompanyId == companyId, cancellationToken); var shipment = await db.InventoryShipments.SingleAsync(x => x.Id == authorization.InventoryShipmentId && x.CompanyId == companyId, cancellationToken);
        if (!shipment.SalesInvoiceId.HasValue) return TransactionResult.Failure("Invoice the original shipment before crediting its return.");
        var invoice = await db.SalesInvoices.SingleOrDefaultAsync(x => x.Id == shipment.SalesInvoiceId.Value && x.CompanyId == companyId, cancellationToken); if (invoice is null || invoice.Status == "Voided") return TransactionResult.Failure("The original sales invoice is unavailable or voided.");
        var receiptLines = await db.CustomerReturnReceiptLines.Where(x => x.CustomerReturnReceiptId == receipt.Id).OrderBy(x => x.Sequence).ToListAsync(cancellationToken); var shipmentLineIds = receiptLines.Select(x => x.InventoryShipmentLineId).ToArray(); var invoiceLines = await db.SalesInvoiceLines.Where(x => x.SalesInvoiceId == invoice.Id && x.InventoryShipmentLineId.HasValue && shipmentLineIds.Contains(x.InventoryShipmentLineId.Value)).ToListAsync(cancellationToken);
        if (invoiceLines.Count != shipmentLineIds.Distinct().Count()) return TransactionResult.Failure("One or more original invoice lines cannot be matched to the returned shipment lines.");
        var priorCreditLines = await (from line in db.CustomerReturnCreditLines join existingCredit in db.CustomerReturnCredits on line.CustomerReturnCreditId equals existingCredit.Id where existingCredit.CompanyId == companyId && existingCredit.Status == "Posted" && invoiceLines.Select(x => x.Id).Contains(line.SalesInvoiceLineId) select line).ToListAsync(cancellationToken);
        var calculated = receiptLines.Select(line =>
        {
            var invoiceLine = invoiceLines.Single(x => x.InventoryShipmentLineId == line.InventoryShipmentLineId); var prior = priorCreditLines.Where(x => x.SalesInvoiceLineId == invoiceLine.Id).ToArray(); var priorQuantity = prior.Sum(x => x.Quantity); if (priorQuantity + line.Quantity > invoiceLine.Quantity) return new { Valid = false, Receipt = line, Invoice = invoiceLine, Net = 0m, Tax = 0m, Total = 0m };
            var originalNet = invoiceLine.LineTotal - invoiceLine.TaxAmount; var final = priorQuantity + line.Quantity == invoiceLine.Quantity; var net = final ? originalNet - prior.Sum(x => x.NetAmount) : RoundCurrency(originalNet * line.Quantity / invoiceLine.Quantity); var tax = final ? invoiceLine.TaxAmount - prior.Sum(x => x.TaxAmount) : RoundCurrency(invoiceLine.TaxAmount * line.Quantity / invoiceLine.Quantity); return new { Valid = true, Receipt = line, Invoice = invoiceLine, Net = RoundCurrency(net), Tax = RoundCurrency(tax), Total = RoundCurrency(net + tax) };
        }).ToArray();
        if (calculated.Any(x => !x.Valid)) return TransactionResult.Failure("The return credit would exceed the quantity on an original invoice line.");
        var subtotal = calculated.Sum(x => x.Net); var taxAmount = calculated.Sum(x => x.Tax); var total = subtotal + taxAmount; if (total <= 0m) return TransactionResult.Failure("The calculated customer return credit must be greater than zero.");
        var revenueIds = calculated.Select(x => x.Invoice.RevenueAccountId).Distinct().ToArray(); var revenue = await db.Accounts.Where(x => x.CompanyId == companyId && revenueIds.Contains(x.Id)).ToDictionaryAsync(x => x.Id, cancellationToken); if (revenue.Count != revenueIds.Length) return TransactionResult.Failure("One or more original revenue accounts are unavailable in this company.");
        if (!await AreActiveTrackingDimensionsAsync(db, companyId, request.CreditDate, calculated.Select(x => (x.Invoice.DepartmentId, x.Invoice.ClassId)), cancellationToken, allowHistorical: true)) return TransactionResult.Failure("One or more original invoice departments or classes are unavailable or incorrectly typed.");
        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken); var creditId = Guid.NewGuid(); var journalLines = calculated.GroupBy(x => new { x.Invoice.RevenueAccountId, x.Invoice.ProjectJobId, x.Invoice.ProjectPhaseId, x.Invoice.ProjectCostCodeId, x.Invoice.DepartmentId, x.Invoice.ClassId }).Select(x => new JournalLineRequest(revenue[x.Key.RevenueAccountId].Number, x.Sum(y => y.Net), 0m, "Returned sale", x.Key.ProjectJobId, x.Key.ProjectPhaseId, x.Key.ProjectCostCodeId, x.Key.DepartmentId, x.Key.ClassId)).ToList(); if (taxAmount > 0m) journalLines.Add(new(OperationalRoleReference(AccountingAccountRoles.SalesTaxPayable), taxAmount, 0m, "Reverse sales tax")); journalLines.Add(new(OperationalRoleReference(AccountingAccountRoles.AccountsReceivable), 0m, total, "Customer return credit"));
        var posting = await PostAsync(db, companyId, request.CreditDate, "Accounts Receivable", creditNumber, request.Reason.Trim(), journalLines, cancellationToken, allowControlAccounts: true, sourceDocumentId: creditId, sourceDocumentType: "CustomerReturnCredit", resolveOperationalRoles: true, allowClosedProjects: true); if (!posting.Succeeded) return posting;
        var sourceApplied = Math.Min(total, invoice.BalanceDue); invoice.BalanceDue -= sourceApplied; invoice.Status = invoice.BalanceDue == 0m ? "Paid" : "Partial"; invoice.ConcurrencyToken = Guid.NewGuid().ToString("N"); var customer = await db.Customers.SingleAsync(x => x.Id == invoice.CustomerId && x.CompanyId == companyId, cancellationToken); customer.OpenBalance -= total;
        var credit = new CustomerReturnCredit { Id = creditId, CompanyId = companyId, CustomerReturnReceiptId = receipt.Id, SalesInvoiceId = invoice.Id, CustomerId = invoice.CustomerId, CreditNumber = creditNumber, CreditDate = request.CreditDate, Reason = request.Reason.Trim(), Subtotal = subtotal, TaxAmount = taxAmount, TotalAmount = total, SourceAppliedAmount = sourceApplied, AppliedAmount = sourceApplied, JournalEntryId = posting.Id!.Value, CreatedByUserId = ResolveUserId(), CreatedAtUtc = DateTimeOffset.UtcNow };
        db.CustomerReturnCredits.Add(credit); db.CustomerReturnCreditLines.AddRange(calculated.Select((x, index) => new CustomerReturnCreditLine { Id = Guid.NewGuid(), CustomerReturnCreditId = credit.Id, CustomerReturnReceiptLineId = x.Receipt.Id, SalesInvoiceLineId = x.Invoice.Id, RevenueAccountId = x.Invoice.RevenueAccountId, Sequence = index + 1, Quantity = x.Receipt.Quantity, NetAmount = x.Net, TaxAmount = x.Tax, TotalAmount = x.Total })); receipt.ConcurrencyToken = Guid.NewGuid().ToString("N");
        AddSalesFulfillmentAudit(db, companyId, "customer-return.credited", nameof(CustomerReturnCredit), credit.Id, new { credit.CreditNumber, receipt.ReceiptNumber, invoice.InvoiceNumber, credit.Subtotal, credit.TaxAmount, credit.TotalAmount, credit.SourceAppliedAmount, availableAmount = credit.TotalAmount - credit.AppliedAmount });
        try { await db.SaveChangesAsync(cancellationToken); } catch (DbUpdateConcurrencyException) { return TransactionResult.Failure("The return receipt or invoice changed while crediting. Refresh and try again."); } catch (DbUpdateException) { return TransactionResult.Failure("The credit number or return credit changed concurrently. Refresh and try again."); }
        await transaction.CommitAsync(cancellationToken); return TransactionResult.Success(credit.Id);
    }

    public async Task<TransactionResult> ApplyCustomerReturnCreditAsync(ApplyCustomerReturnCreditRequest request, CancellationToken cancellationToken = default)
    {
        if (!HasPermission(BrassLedgerPermissions.ReceivablesManage)) return TransactionResult.Failure("You are not authorized to apply customer credits.");
        var amount = RoundCurrency(request.Amount); if (amount <= 0m) return TransactionResult.Failure("A positive credit application amount is required.");
        await using var db = await dbContextFactory.CreateDbContextAsync(cancellationToken); var companyId = await ResolveCompanyIdAsync(db, cancellationToken); var credit = await db.CustomerReturnCredits.SingleOrDefaultAsync(x => x.Id == request.CustomerReturnCreditId && x.CompanyId == companyId, cancellationToken);
        if (credit is null || credit.Status != "Posted") return TransactionResult.Failure("Only a posted customer return credit can be applied."); if (!string.Equals(credit.ConcurrencyToken, request.ConcurrencyToken, StringComparison.Ordinal)) return TransactionResult.Failure("The customer return credit changed after it was opened. Refresh and review it again."); if (request.AppliedOn < credit.CreditDate) return TransactionResult.Failure("The application date cannot precede the credit date.");
        if (await IsClosedPeriodAsync(db, companyId, request.AppliedOn, cancellationToken)) return TransactionResult.Failure("The credit application date is in a closed accounting period.");
        var available = credit.TotalAmount - credit.AppliedAmount - credit.RefundedAmount; if (amount > available) return TransactionResult.Failure("The application exceeds the available customer credit."); var invoice = await db.SalesInvoices.SingleOrDefaultAsync(x => x.Id == request.SalesInvoiceId && x.CompanyId == companyId && x.CustomerId == credit.CustomerId, cancellationToken); if (invoice is null || invoice.Status == "Voided") return TransactionResult.Failure("Select an active invoice for the same customer."); if (amount > invoice.BalanceDue) return TransactionResult.Failure("The application exceeds the invoice balance.");
        var application = new CustomerReturnCreditApplication { Id = Guid.NewGuid(), CompanyId = companyId, CustomerReturnCreditId = credit.Id, SalesInvoiceId = invoice.Id, AppliedOn = request.AppliedOn, Amount = amount, AppliedByUserId = ResolveUserId(), AppliedAtUtc = DateTimeOffset.UtcNow }; db.CustomerReturnCreditApplications.Add(application); credit.AppliedAmount += amount; credit.ConcurrencyToken = Guid.NewGuid().ToString("N"); invoice.BalanceDue -= amount; invoice.Status = invoice.BalanceDue == 0m ? "Paid" : "Partial"; invoice.ConcurrencyToken = Guid.NewGuid().ToString("N"); AddSalesFulfillmentAudit(db, companyId, "customer-return.credit.applied", nameof(CustomerReturnCreditApplication), application.Id, new { credit.CreditNumber, invoice.InvoiceNumber, application.Amount, application.AppliedOn });
        try { await db.SaveChangesAsync(cancellationToken); } catch (DbUpdateConcurrencyException) { return TransactionResult.Failure("The credit or invoice changed while applying it. Refresh and try again."); }
        return TransactionResult.Success(application.Id);
    }

    public async Task<TransactionResult> ReverseCustomerReturnCreditApplicationAsync(ReverseCustomerReturnCreditApplicationRequest request, CancellationToken cancellationToken = default)
    {
        if (!HasPermission(BrassLedgerPermissions.PaymentReverse)) return TransactionResult.Failure("You are not authorized to reverse customer credit applications."); if (string.IsNullOrWhiteSpace(request.Reason)) return TransactionResult.Failure("A reversal reason is required.");
        await using var db = await dbContextFactory.CreateDbContextAsync(cancellationToken); var companyId = await ResolveCompanyIdAsync(db, cancellationToken); var application = await db.CustomerReturnCreditApplications.SingleOrDefaultAsync(x => x.Id == request.CustomerReturnCreditApplicationId && x.CompanyId == companyId, cancellationToken); if (application is null || application.Status != "Posted") return TransactionResult.Failure("Only a posted customer credit application can be reversed."); if (!string.Equals(application.ConcurrencyToken, request.ConcurrencyToken, StringComparison.Ordinal)) return TransactionResult.Failure("The credit application changed after it was opened. Refresh and review it again."); if (request.ReversalDate < application.AppliedOn) return TransactionResult.Failure("The reversal date cannot precede the application date."); if (await IsClosedPeriodAsync(db, companyId, request.ReversalDate, cancellationToken)) return TransactionResult.Failure("The credit application reversal date is in a closed accounting period."); var credit = await db.CustomerReturnCredits.SingleAsync(x => x.Id == application.CustomerReturnCreditId && x.CompanyId == companyId, cancellationToken); var invoice = await db.SalesInvoices.SingleAsync(x => x.Id == application.SalesInvoiceId && x.CompanyId == companyId, cancellationToken);
        application.Status = "Reversed"; application.ReversedByUserId = ResolveUserId(); application.ReversedAtUtc = DateTimeOffset.UtcNow; application.ReversalDate = request.ReversalDate; application.ReversalReason = request.Reason.Trim(); application.ConcurrencyToken = Guid.NewGuid().ToString("N"); credit.AppliedAmount -= application.Amount; credit.ConcurrencyToken = Guid.NewGuid().ToString("N"); invoice.BalanceDue += application.Amount; invoice.Status = invoice.BalanceDue == invoice.TotalAmount ? "Open" : "Partial"; invoice.ConcurrencyToken = Guid.NewGuid().ToString("N"); AddSalesFulfillmentAudit(db, companyId, "customer-return.credit-application.reversed", nameof(CustomerReturnCreditApplication), application.Id, new { credit.CreditNumber, invoice.InvoiceNumber, application.Amount, application.ReversalDate, application.ReversalReason }); try { await db.SaveChangesAsync(cancellationToken); } catch (DbUpdateConcurrencyException) { return TransactionResult.Failure("The credit application changed while reversing. Refresh and try again."); }
        return TransactionResult.Success(application.Id);
    }

    public async Task<TransactionResult> RefundCustomerReturnCreditAsync(RefundCustomerReturnCreditRequest request, CancellationToken cancellationToken = default)
    {
        if (!HasPermission(BrassLedgerPermissions.ReceivablesManage)) return TransactionResult.Failure("You are not authorized to refund customer credits."); var amount = RoundCurrency(request.Amount); if (amount <= 0m || string.IsNullOrWhiteSpace(request.Reference)) return TransactionResult.Failure("A positive refund amount and reference are required.");
        await using var db = await dbContextFactory.CreateDbContextAsync(cancellationToken); var companyId = await ResolveCompanyIdAsync(db, cancellationToken); var credit = await db.CustomerReturnCredits.SingleOrDefaultAsync(x => x.Id == request.CustomerReturnCreditId && x.CompanyId == companyId, cancellationToken); if (credit is null || credit.Status != "Posted") return TransactionResult.Failure("Only a posted customer return credit can be refunded."); if (!string.Equals(credit.ConcurrencyToken, request.ConcurrencyToken, StringComparison.Ordinal)) return TransactionResult.Failure("The customer return credit changed after it was opened. Refresh and review it again."); if (request.RefundDate < credit.CreditDate) return TransactionResult.Failure("The refund date cannot precede the credit date."); if (amount > credit.TotalAmount - credit.AppliedAmount - credit.RefundedAmount) return TransactionResult.Failure("The refund exceeds the available customer credit."); if (await db.CustomerReturnCreditRefunds.AnyAsync(x => x.CompanyId == companyId && x.Reference == request.Reference.Trim(), cancellationToken)) return TransactionResult.Failure("Customer credit refund reference already exists."); var bank = await db.BankAccounts.SingleOrDefaultAsync(x => x.Id == request.BankAccountId && x.CompanyId == companyId, cancellationToken); if (bank is null) return TransactionResult.Failure("Bank account not found."); if (bank.CurrentBalance < amount) return TransactionResult.Failure("The bank account does not have enough book balance for this refund."); var cash = await ResolveBankLedgerAccountNumberAsync(db, companyId, bank, cancellationToken); if (string.IsNullOrWhiteSpace(cash)) return TransactionResult.Failure("The bank account is not mapped to an active ledger account.");
        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken); var refundId = Guid.NewGuid(); var posting = await PostAsync(db, companyId, request.RefundDate, "Accounts Receivable", request.Reference.Trim(), $"Refund customer return credit {credit.CreditNumber}", [new(OperationalRoleReference(AccountingAccountRoles.AccountsReceivable), amount, 0m, "Settle customer credit"), new(cash, 0m, amount, "Customer refund")], cancellationToken, bank.Id, true, refundId, "CustomerReturnCreditRefund", true); if (!posting.Succeeded) return posting;
        var refund = new CustomerReturnCreditRefund { Id = refundId, CompanyId = companyId, CustomerReturnCreditId = credit.Id, BankAccountId = bank.Id, Reference = request.Reference.Trim(), RefundDate = request.RefundDate, Amount = amount, JournalEntryId = posting.Id!.Value, RefundedByUserId = ResolveUserId(), RefundedAtUtc = DateTimeOffset.UtcNow }; db.CustomerReturnCreditRefunds.Add(refund); credit.RefundedAmount += amount; credit.ConcurrencyToken = Guid.NewGuid().ToString("N"); bank.CurrentBalance -= amount; bank.UnreconciledAmount += amount; bank.ConcurrencyToken = Guid.NewGuid().ToString("N"); (await db.Customers.SingleAsync(x => x.Id == credit.CustomerId && x.CompanyId == companyId, cancellationToken)).OpenBalance += amount; AddSalesFulfillmentAudit(db, companyId, "customer-return.credit.refunded", nameof(CustomerReturnCreditRefund), refund.Id, new { credit.CreditNumber, refund.Reference, refund.Amount, refund.RefundDate }); try { await db.SaveChangesAsync(cancellationToken); } catch (DbUpdateConcurrencyException) { return TransactionResult.Failure("The credit or bank account changed while refunding. Refresh and try again."); } catch (DbUpdateException) { return TransactionResult.Failure("The refund reference changed concurrently. Refresh and try again."); }
        await transaction.CommitAsync(cancellationToken); return TransactionResult.Success(refund.Id);
    }

    public async Task<TransactionResult> ReverseCustomerReturnCreditRefundAsync(ReverseCustomerReturnCreditRefundRequest request, CancellationToken cancellationToken = default)
    {
        if (!HasPermission(BrassLedgerPermissions.PaymentReverse)) return TransactionResult.Failure("You are not authorized to reverse customer credit refunds."); if (string.IsNullOrWhiteSpace(request.Reason)) return TransactionResult.Failure("A reversal reason is required."); await using var db = await dbContextFactory.CreateDbContextAsync(cancellationToken); var companyId = await ResolveCompanyIdAsync(db, cancellationToken); var refund = await db.CustomerReturnCreditRefunds.SingleOrDefaultAsync(x => x.Id == request.CustomerReturnCreditRefundId && x.CompanyId == companyId, cancellationToken); if (refund is null || refund.Status != "Posted") return TransactionResult.Failure("Only a posted customer credit refund can be reversed."); if (!string.Equals(refund.ConcurrencyToken, request.ConcurrencyToken, StringComparison.Ordinal)) return TransactionResult.Failure("The customer credit refund changed after it was opened. Refresh and review it again."); if (request.ReversalDate < refund.RefundDate) return TransactionResult.Failure("The reversal date cannot precede the refund date."); if (await IsInCompletedReconciliationAsync(db, refund.JournalEntryId, cancellationToken)) return TransactionResult.Failure("A reconciled refund cannot be reversed until its bank reconciliation is reopened."); await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken); var reversal = await PostInverseAsync(db, companyId, refund.JournalEntryId, request.ReversalDate, $"REV-{refund.Reference}", request.Reason.Trim(), refund.Id, "CustomerReturnCreditRefundReversal", refund.BankAccountId, cancellationToken, "Accounts Receivable"); if (!reversal.Succeeded) return reversal; var credit = await db.CustomerReturnCredits.SingleAsync(x => x.Id == refund.CustomerReturnCreditId && x.CompanyId == companyId, cancellationToken); var bank = await db.BankAccounts.SingleAsync(x => x.Id == refund.BankAccountId && x.CompanyId == companyId, cancellationToken); refund.Status = "Reversed"; refund.ReversalJournalEntryId = reversal.Id; refund.ReversedByUserId = ResolveUserId(); refund.ReversedAtUtc = DateTimeOffset.UtcNow; refund.ReversalReason = request.Reason.Trim(); refund.ConcurrencyToken = Guid.NewGuid().ToString("N"); credit.RefundedAmount -= refund.Amount; credit.ConcurrencyToken = Guid.NewGuid().ToString("N"); bank.CurrentBalance += refund.Amount; bank.UnreconciledAmount += refund.Amount; bank.ConcurrencyToken = Guid.NewGuid().ToString("N"); (await db.Customers.SingleAsync(x => x.Id == credit.CustomerId && x.CompanyId == companyId, cancellationToken)).OpenBalance -= refund.Amount; AddSalesFulfillmentAudit(db, companyId, "customer-return.credit-refund.reversed", nameof(CustomerReturnCreditRefund), refund.Id, new { refund.Reference, refund.Amount, request.ReversalDate, reason = request.Reason.Trim() }); try { await db.SaveChangesAsync(cancellationToken); } catch (DbUpdateConcurrencyException) { return TransactionResult.Failure("The refund changed while reversing. Refresh and try again."); }
        await transaction.CommitAsync(cancellationToken); return TransactionResult.Success(refund.Id);
    }

    public async Task<TransactionResult> ReverseCustomerReturnCreditAsync(ReverseCustomerReturnCreditRequest request, CancellationToken cancellationToken = default)
    {
        if (!HasPermission(BrassLedgerPermissions.PaymentReverse)) return TransactionResult.Failure("You are not authorized to reverse customer return credits."); if (string.IsNullOrWhiteSpace(request.Reason)) return TransactionResult.Failure("A reversal reason is required."); await using var db = await dbContextFactory.CreateDbContextAsync(cancellationToken); var companyId = await ResolveCompanyIdAsync(db, cancellationToken); var credit = await db.CustomerReturnCredits.SingleOrDefaultAsync(x => x.Id == request.CustomerReturnCreditId && x.CompanyId == companyId, cancellationToken); if (credit is null || credit.Status != "Posted") return TransactionResult.Failure("Only a posted customer return credit can be reversed."); if (!string.Equals(credit.ConcurrencyToken, request.ConcurrencyToken, StringComparison.Ordinal)) return TransactionResult.Failure("The customer return credit changed after it was opened. Refresh and review it again."); if (request.ReversalDate < credit.CreditDate) return TransactionResult.Failure("The reversal date cannot precede the credit date."); if (credit.AppliedAmount != credit.SourceAppliedAmount || credit.RefundedAmount != 0m || await db.CustomerReturnCreditApplications.AnyAsync(x => x.CompanyId == companyId && x.CustomerReturnCreditId == credit.Id && x.Status == "Posted", cancellationToken) || await db.CustomerReturnCreditRefunds.AnyAsync(x => x.CompanyId == companyId && x.CustomerReturnCreditId == credit.Id && x.Status == "Posted", cancellationToken)) return TransactionResult.Failure("Reverse all later credit applications and refunds before reversing the return credit.");
        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken); var reversal = await PostInverseAsync(db, companyId, credit.JournalEntryId, request.ReversalDate, $"REV-{credit.CreditNumber}", request.Reason.Trim(), credit.Id, "CustomerReturnCreditReversal", null, cancellationToken, "Accounts Receivable"); if (!reversal.Succeeded) return reversal; var invoice = await db.SalesInvoices.SingleAsync(x => x.Id == credit.SalesInvoiceId && x.CompanyId == companyId, cancellationToken); invoice.BalanceDue += credit.SourceAppliedAmount; invoice.Status = invoice.BalanceDue == invoice.TotalAmount ? "Open" : invoice.BalanceDue == 0m ? "Paid" : "Partial"; invoice.ConcurrencyToken = Guid.NewGuid().ToString("N"); (await db.Customers.SingleAsync(x => x.Id == credit.CustomerId && x.CompanyId == companyId, cancellationToken)).OpenBalance += credit.TotalAmount; credit.Status = "Reversed"; credit.ReversalJournalEntryId = reversal.Id; credit.ReversedByUserId = ResolveUserId(); credit.ReversedAtUtc = DateTimeOffset.UtcNow; credit.ReversalDate = request.ReversalDate; credit.ReversalReason = request.Reason.Trim(); credit.ConcurrencyToken = Guid.NewGuid().ToString("N"); var receipt = await db.CustomerReturnReceipts.SingleAsync(x => x.Id == credit.CustomerReturnReceiptId && x.CompanyId == companyId, cancellationToken); receipt.ConcurrencyToken = Guid.NewGuid().ToString("N"); AddSalesFulfillmentAudit(db, companyId, "customer-return.credit.reversed", nameof(CustomerReturnCredit), credit.Id, new { credit.CreditNumber, credit.TotalAmount, credit.ReversalDate, credit.ReversalReason }); try { await db.SaveChangesAsync(cancellationToken); } catch (DbUpdateConcurrencyException) { return TransactionResult.Failure("The customer return credit changed while reversing. Refresh and try again."); }
        await transaction.CommitAsync(cancellationToken); return TransactionResult.Success(credit.Id);
    }
}
